import {P} from './palette.js';
import {oval,line,shape,shadow} from './shapes.js';
import {blink,clamp} from './animation.js';
export function zombieFace(c,t,uid,hit=0){oval(c,0,-14,13,14,hit>.1?P.hit:P.skin);oval(c,-6,-10,5,6,P.skinShade,false);oval(c,-5,-17,4,4.2*blink(t,uid),P.cream);oval(c,5,-15,3.2,3.4*blink(t,uid),P.cream);oval(c,-4,-17,1.5,2,P.ink,false);oval(c,5,-14,1.2,1.6,P.ink,false);line(c,[[-5,-6],[1,-4],[7,-6]],P.ink,2);shape(c,[[0,-5],[0,-1],[3,-1],[3,-5]],P.cream);line(c,[[-9,-24],[-7,-30],[-4,-26]],P.ink,2)}
function cone(c,t,ratio){c.save();c.translate(0,-25);c.rotate(Math.sin(t*2)*.045+(1-ratio)*.22);shape(c,[[-15,0],[-5,-25],[1,-29],[7,-15],[14,1]],P.fire);shape(c,[[-9,-11],[9,-10],[6,-17],[-6,-18]],P.cream);shape(c,[[-5,-25],[1,-29],[4,-21],[0,-23]],P.gold);oval(c,0,1,17,3,P.fire);if(ratio<.6)line(c,[[8,-5],[2,-9],[7,-12]],P.bark,1.5);c.restore()}
function bucket(c,t,ratio){c.save();c.translate(0,-24);c.rotate(Math.sin(t)*.025+(1-ratio)*-.16);shape(c,[[-15,-17],[13,-17],[16,2],[-15,2]],P.metal);oval(c,-1,-17,14,3,P.metalDark);line(c,[[-9,-12],[-8,-1]],P.cream,3);line(c,[[-15,-8],[-20,-5],[-17,9],[11,10],[19,-4],[14,-8]],P.metalDark,2);if(ratio<.7)line(c,[[8,-12],[3,-8],[9,-7]],P.metalDark,2);if(ratio<.35)line(c,[[-3,-3],[2,-6],[5,0]],P.metalDark,2);c.restore()}
export function drawZombie(c,z,x,y,time,o={}){const t=time+(z.uid||0)*1.31,walk=o.moving===false?0:Math.sin(t*6),attack=o.attack||0,ratio=clamp(z.hp/z.maxHp);c.save();c.translate(x,y);shadow(c,0,22,16);if(o.death){c.globalAlpha*=1-o.death;c.translate(o.death*12,o.death*8);c.rotate(o.death*1.3)}c.rotate(Math.sin(t*3)*.045+(o.hit||0)*-.2);for(const side of [-1,1]){c.save();c.translate(side*6,8);c.rotate(side*walk*.2);line(c,[[0,0],[side*2,9],[side*2,15]],P.clothDark,7);oval(c,side*2+2,16,6,3.5,P.shoe);c.restore()}c.save();c.translate(0,-Math.abs(walk)*1.5);shape(c,[[-10,-6],[9,-8],[13,8],[6,12],[-10,10],[-13,1]],P.cloth);shape(c,[[-4,-5],[2,-6],[5,9],[-2,10]],P.clothDark);line(c,[[-8,2],[-4,3]],P.cream,1);for(const side of [-1,1]){c.save();c.translate(side*10,-2);c.rotate(side*(.1+walk*.1)-attack*.9);line(c,[[0,0],[side*3,7],[side*2+attack*8,12-attack*13]],P.clothDark,6);oval(c,side*2+attack*8,12-attack*13,4.5,5,P.skin);line(c,[[side*2+attack*8,12-attack*13],[side*5+attack*8,14-attack*13]],P.skinShade,1);c.restore()}c.save();c.translate(Math.sin(t*3+.5)*1.4,-attack*2);c.rotate(-attack*.12);zombieFace(c,t,z.uid,o.hit);if(z.tier===1||z.id==='conehead')cone(c,t,ratio);if(z.tier===2||z.id==='buckethead')bucket(c,t,ratio);c.restore();c.restore();c.restore()}
